#include "parksmart.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
static void help(void){puts("Commands: list | reserve ID DRIVER START END | cancel ID | nearest NODE START END | compare NODE1,NODE2,... START END | report | benchmark | demo | help");}
static void list(const System*s){puts("ID | Name | Node | Capacity | Occupied | Rate/hr | Active");for(int i=0;i<s->count;i++){const Space*p=&s->spaces[i];printf("%d | %s | %d | %d | %d | %d | %d\n",p->id,p->name,p->node,p->capacity,p->occupied,p->rate,p->active);}}
static void report(const System*s){int cap=0,used=0,active=0;for(int i=0;i<s->count;i++)if(s->spaces[i].active){cap+=s->spaces[i].capacity;used+=s->spaces[i].occupied;}for(int i=0;i<s->rcount;i++)active+=s->reservations[i].active;printf("Total capacity: %d | Occupied now: %d | Active reservations: %d | Available now (before reservations): %d\n",cap,used,active,cap-used);}
static void compare(const System*s,const int*d,int n,int start,int end){int a[32],b[32],ca=0,cb=0;clock_t t=clock();int na=greedy_assign(s,d,n,start,end,a,&ca);double ta=(double)(clock()-t)/CLOCKS_PER_SEC*1000;t=clock();int nb=optimal_assign(s,d,n,start,end,b,&cb);double tb=(double)(clock()-t)/CLOCKS_PER_SEC*1000;printf("Greedy: assigned=%d distance=%d time_ms=%.4f\n",na,ca,ta);printf("Optimal min-cost flow: assigned=%d distance=%d time_ms=%.4f\n",nb,cb,tb);for(int i=0;i<n;i++)printf("Driver %d (node %d): greedy=%d optimal=%d\n",i+1,d[i],a[i],b[i]);}
int main(int argc,char**argv){System*s=malloc(sizeof(System));if(!s)return 1;const char*dir=getenv("PARKSMART_DATA");if(!dir)dir="data";load_system(s,dir);if(argc<2){help();free(s);return 0;}if(!strcmp(argv[1],"list"))list(s);else if(!strcmp(argv[1],"report"))report(s);else if(!strcmp(argv[1],"reserve")&&argc==6){int id=reserve_space(s,atoi(argv[2]),argv[3],atoi(argv[4]),atoi(argv[5]));if(id>0){save_system(s,dir);printf("SUCCESS reservation_id=%d\n",id);}else printf("ERROR code=%d\n",id);}else if(!strcmp(argv[1],"cancel")&&argc==3){int ok=cancel_reservation(s,atoi(argv[2]));if(ok)save_system(s,dir);puts(ok?"SUCCESS cancelled":"ERROR reservation not found");}else if(!strcmp(argv[1],"nearest")&&argc==5){int distance=0,idx=nearest_space(s,atoi(argv[2]),atoi(argv[3]),atoi(argv[4]),&distance);if(idx>=0)printf("Nearest: ID=%d NAME=%s DISTANCE=%d RATE=%d\n",s->spaces[idx].id,s->spaces[idx].name,distance,s->spaces[idx].rate);else puts("No reachable available space");}else if(!strcmp(argv[1],"compare")&&argc==5){int d[32],n=0;char buf[512];snprintf(buf,sizeof(buf),"%s",argv[2]);char*tok=strtok(buf,",");while(tok&&n<32){d[n++]=atoi(tok);tok=strtok(NULL,",");}compare(s,d,n,atoi(argv[3]),atoi(argv[4]));}else if(!strcmp(argv[1],"benchmark")){int n=20000,*a=malloc((size_t)n*sizeof(int)),*b=malloc((size_t)n*sizeof(int));if(a&&b){srand(42);for(int i=0;i<n;i++)a[i]=rand();memcpy(b,a,(size_t)n*sizeof(int));clock_t t=clock();merge_sort(a,n);double m=(double)(clock()-t)/CLOCKS_PER_SEC*1000;t=clock();quick_sort(b,n);double q=(double)(clock()-t)/CLOCKS_PER_SEC*1000;printf("20,000 integers: merge sort %.3f ms; quick sort %.3f ms\n",m,q);}free(a);free(b);}else if(!strcmp(argv[1],"demo")){puts("NORMAL OPERATION");int d[]={0,1,2,3,4,5};compare(s,d,6,10,12);puts("CAPACITY SHOCK (disable first 4 lots)");for(int i=0;i<4&&i<s->count;i++)s->spaces[i].active=0;compare(s,d,6,10,12);puts("STRESS CASE (32 drivers)");int large[32];for(int i=0;i<32;i++)large[i]=i%s->nodes;compare(s,large,32,14,16);}else help();free(s);return 0;}
